INSERT INTO api.master_nyans (no, name, reading, motif, first_appeared, episode, prompt_ja, prompt_en, dialogue, dialogue_meaning, has_story, custom_image_url, raw_image_url, has_custom_image, favorite_items, favorite_locations)
VALUES
(1, 'かがみもちにゃん / しょよがつにゃん', 'かがみもちにゃん', 'お正月・鏡餅・門松', 'Date(2023,0,4)', 'お正月のめでたい象徴として頭に鏡餅やしめ縄を乗せて登場。大晦日から正月気分が抜けず三輪車を漕ぎまくる。', 'シンプルな黒インクペン画のぽてっとした猫「かがみもちにゃん」。頭の上に小さな鏡餅とみかんを乗せ、真顔でちょこんと座っている。脱力系マスコット風イラスト。', 'minimalist cute cat mascot named Kagamimochi-nyan with a tiny traditional tiered mochi and mandarin orange balanced on its head, deadpan stoic face, simple black ink pen lines, charming Japanese indie character style --ar 1:1', 'うにゃーんにゃ！（すぽっ）', '「お正月だから鏡餅頭に乗せて三輪車で爆走するにゃ！お年玉もちょうだいにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(2, 'くぁべぎにゃん', 'くぁべぎにゃん', '韓国ツイストドーナツ（クァベギ）・大須', 'Date(2023,0,10)', '大須で話題の韓国風ねじりドーナツ「クァベギ」を毎朝手作りして広めようとする職人気質なスイーツ猫。', 'シンプルなペン画の猫「くぁべぎにゃん」。ねじりドーナツ（クァベギ）を首にマフラーのように巻き、粉砂糖をまぶして誇らしげに立っている。脱力系イラスト。', 'minimalist cute cat mascot named Kwabaegi-nyan wearing a twisted sugar doughnut around its neck like a scarf, deadpan proud expression, clean black line art, charming Japanese indie style --ar 1:1', 'にゃーうんにゃ！（ねじねじ）', '「大須名物の揚げたてクァベギはいかがかにゃ？粉砂糖たっぷりで美味しいにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(3, 'こめだにゃん / しろのわーるにゃん', 'こめだにゃん', 'コメダ珈琲店・シロノワール', 'Date(2023,0,12)', 'コメダ珈琲でシロノワールを食べまくり、チョコがかかりすぎて「くろのわーるにゃん」に闇堕ちする猫。', 'シンプルなペン画の丸っこい猫「しろのわーるにゃん」。頭にデニッシュパンとソフトクリーム、チェリーを乗せてスプーンを持っている脱力系イラスト。', 'minimalist chubby cat mascot named Shironoir-nyan with a warm Danish pastry and soft serve ice cream on its head, holding a tiny dessert spoon with a deadpan face, black ink pen drawing --ar 1:1', 'うにゃにゃー！（どろり）', '「シロノワール食べすぎてチョコまみれの闇堕ちくろのわーるになったにゃ…」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(4, 'いちけいのからすにゃん', 'いちけいのからすにゃん', 'ドラマ『イチケイのカラス』・裁判所食堂カレーうどん', 'Date(2023,0,16)', '裁判官風の黒い法服を着て食堂の豊橋カレーうどん職権発動を連発。後に脱法して屋台カレー店を開業しようと企む。', '黒い裁判官の法服を着たシンプルなペン画の猫「いちけいのからすにゃん」。首から木槌をぶら下げ、カレーうどんの丼を前に真顔で木槌を構えている脱力系マスコット。', 'minimalist cute cat mascot named Ichikei-no-Karasu-nyan wearing black judicial robes with a tiny gavel around its neck, sitting stoically in front of a curry udon bowl, simple line art --ar 1:1', 'にゃっ！（トントン）', '「職権発動！食堂の豊橋カレーうどんを全員大盛りに処すにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(5, 'こっとにゃん', 'こっとにゃん', 'キャンプ用コット（簡易ベッド）・極上の寝心地', 'Date(2023,0,23)', 'キャンプ用コットの最高の寝心地を追求し、ピンと張った布の弾力で毎日筋トレに励むマッチョ志望の猫。', 'シンプルなペン画のぽてっとした猫「こっとにゃん」。小さなキャンプ用折りたたみコットの上に大の字で寝転がり、至福の無表情を浮かべている脱力系イラスト。', 'minimalist cute cat mascot named Cot-nyan lying flat on a miniature camping cot with a delightfully relaxed deadpan face, clean black pen lines, Japanese character design --ar 1:1', 'うにゃ〜ん（みしみし）', '「コットの張りと寝心地が最高すぎて永遠に起きたくないにゃ…」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(6, 'ひにちぐすりにゃん', 'ひにちぐすりにゃん', '日にち薬・時間の経過', 'Date(2023,0,30)', '「飲めば毎日が金曜日（またはキャンプ当日）になる」という怪しい特効薬を売り歩く、自称ヒーロー猫。', 'シンプルな黒ペン画の猫「ひにちぐすりにゃん」。カプセル薬の形をした小さなリュックを背負い、怪しげな薬瓶を掲げて真顔で立っている。脱力系マスコット。', 'minimalist quirky cat mascot named Hinichigusuri-nyan wearing a tiny capsule-shaped backpack and holding up a small funny medicine bottle with a deadpan face, clean line art --ar 1:1', 'にゃにゃっ！（チャリン）', '「飲めば毎日が金曜日になる怪しい特効薬はいかがかにゃ？」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(7, 'えほうまきにゃん', 'えほうまきにゃん', '節分・恵方巻', 'Date(2023,1,3)', '太巻きの海苔に全身を包まれてすっぽり収まり、無言で恵方を向きながらもぐもぐしている猫。', 'シンプルなペン画の猫「えほうまきにゃん」。恵方巻の海苔巻きの中にすっぽり入り、顔と尻尾だけ出して真顔で恵方を向いている。脱力系イラスト。', 'minimalist cute cat mascot named Ehomaki-nyan tucked snugly inside a giant sushi roll like a sleeping bag, poking its head out with a deadpan face, simple pen lines --ar 1:1', 'もぐもぐ…（じーっ）', '「恵方巻の海苔巻きにすっぽり収まって無言で恵方を向いてるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(8, 'すもあにゃん / こすもあにゃん', 'すもあにゃん', 'キャンプスイーツ（スモア・焼きマシュマロ）・アウトドアチェア', 'Date(2023,1,6)', 'お洒落なキャンプチェアに座り、コーヒー豆を焙煎しすぎて炭（灰）にする。相棒の「こすもあにゃん」と並んでお洒落空間を演出する。', 'シンプルなペン画の猫「すもあにゃん」。頭にマシュマロとチョコを挟んだクラッカーを乗せ、小さなアウトドアチェアにちょこんと座っている脱力系マスコット。', 'minimalist cute cat mascot named S''more-nyan with a toasted marshmallow and chocolate graham cracker on its head, sitting quietly on a tiny camp chair with a deadpan stoic face, pen art --ar 1:1', 'うにゃふにゃ〜（ぱちぱち）', '「キャンプチェアでコーヒー豆を焙煎しすぎて炭にしちゃったにゃ…」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(9, 'いぬやまおーとにゃん', 'いぬやまおーとにゃん', '犬山オートキャンプ場・平日のデイキャンプ', 'Date(2023,1,20)', '平日の客引きのために六番町までやってきて、雨の日のキャンプを「オツ！」と絶賛して普及しようとする猫。', 'シンプルなペン画の猫「いぬやまおーとにゃん」。小さなタープを背負い、雨合羽を着て「おっつ！」とポーズをとっている脱力系イラスト。', 'minimalist camping cat mascot named Inuyama-Auto-nyan wearing a tiny yellow raincoat and carrying miniature tent poles with a funny enthusiastic deadpan face, clean line art --ar 1:1', 'おっつ！にゃーにゃ！', '「雨の日の犬山キャンプこそオツだにゃ！六番町まで客引きに来たにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(10, 'あんとにゃん / はちにゃん', 'あんとにゃん', '映画『アントマン＆ワスプ』・昆虫ヒーロー', 'Date(2023,1,23)', 'アベンニャーズの一員。小さくなるスーパーパワーで虫たちを操ろうとするが、季節外れの蜂に追い回される。', 'シンプルなペン画の猫「あんとにゃん」。小さなアリの触角がついたヘルメットをかぶり、ミニチュアサイズで仁王立ちしている脱力系ヒーロー猫。', 'minimalist tiny superhero cat mascot named Ant-nyan wearing a cute helmet with ant antennae, standing bravely with a deadpan serious face, simple black ink pen drawing --ar 1:1', 'にゃにゃーん！（しゅたっ）', '「アベンニャーズの一員アントマンだにゃ！ハチに追われてピンチにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(11, 'あるこばにゃん', 'あるこばにゃん', '薪焼き料理・レストラン「アルコバ」・薪焼きスイーツ', 'Date(2023,1,26)', '薪焼きの美味しさに取り憑かれ、何でも薪で焼いてしまう（GODIVAのチョコや胃薬の正露丸まで薪焼きにする）熱血シェフ猫。', 'シンプルなペン画の猫「あるこばにゃん」。小さなコック帽をかぶり、薪の束を抱えてパチパチ燃える小さな焚き火の前に真顔で立っている。脱力系イラスト。', 'minimalist chef cat mascot named Alcoba-nyan wearing a tiny white toque hat, holding a bundle of firewood next to a miniature cooking fire with a deadpan face, clean pen lines --ar 1:1', 'めらめら！にゃにゃー！', '「薪焼きの美味さに目覚めたにゃ！チョコも正露丸も全部薪で焼いてやるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(12, 'らんたんにゃん', 'らんたんにゃん', 'キャンプ用LEDランタン・オイルランタン', 'Date(2023,2,13)', '暗闇を照らすランタン猫。大気圏突入ロケットになったり、7体合体して巨大な光る仏像ロボ「かさじぞうランタン」に変形する。', 'シンプルなペン画の猫「らんたんにゃん」。お腹がランタンのガラスホヤになっており、ぽわっと光りながら真顔で立っている脱力系マスコット。', 'minimalist cute cat mascot named Lantern-nyan with a glowing retro lantern belly, emitting a soft warm light with a comical deadpan stoic face, simple black ink line art --ar 1:1', 'ぴかーっ！にゃにゃー！', '「お腹のランタンが光るにゃ！7体合体して巨大仏像ロボに変形するにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(13, 'さんりんにゃん', 'さんりんにゃん', '三輪車・改造メカニック', 'Date(2023,3,6)', '由美さんの愛車・三輪車をジェットエンジンや超高速ギアで改造しようとする暴走メカニック猫。', 'シンプルなペン画の猫「さんりんにゃん」。小さな赤い三輪車に真顔で乗り、ハンドルにスパナを取り付けている脱力系イラスト。', 'minimalist funny cat mascot named Sanrin-nyan riding a tiny vintage red tricycle, holding a miniature wrench with a serious deadpan expression, simple pen drawing --ar 1:1', 'ばばばばっ！（キコキコ）', '「三輪車にジェットエンジンと超高速ギアを取り付けて暴走させるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(14, 'すぎかふんにゃん / ぶたくさかふんにゃん', 'すぎかふんにゃん', '春の花粉症・スギ花粉・ブタクサ', 'Date(2023,3,11)', 'スギ花粉の黄色い粉をまき散らしながら「特製スギ花粉生搾りジュース」を売りつけようとする厄介な花粉猫。', 'シンプルなペン画の猫「すぎかふんにゃん」。黄色いスギ花粉のポンポンを頭に乗せ、ティッシュ箱を抱えてくしゃみ寸前の真顔をしている脱力系マスコット。', 'minimalist funny cat mascot named Sugikafun-nyan with a fluffy yellow pollen pom-pom on its head, holding a tissue box with a deadpan squinting face, clean line art --ar 1:1', 'ふにゃっくしょん！（ぶへっ）', '「特製スギ花粉生搾りジュースはいかがかにゃ？ティッシュくれにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(15, 'まくらにゃん', 'まくらにゃん', 'キャンプ用枕・快眠ギア', 'Date(2023,3,17)', 'キャンプでの安眠を追求し、手作りのふわふわ枕を背負って売り歩く快眠プロデューサー猫。', 'シンプルなペン画の猫「まくらにゃん」。ふかふかの枕を背中にリュックのように背負い、眠そうな半目で立っている脱力系イラスト。', 'minimalist sleepy cat mascot named Makura-nyan carrying a soft plush pillow strapped to its back like a backpack, deadpan drowsy face, simple black ink pen lines --ar 1:1', 'ふにゃぁ…（ぐーぐー）', '「手作りの極上ふわふわ枕を背負って快眠をお届けに来たにゃ…」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(16, 'きそさんせんにゃん', 'きそさんせんにゃん', '木曽三川公園・デイキャンプマナー指導', 'Date(2023,3,24)', '木曽三川の美しい自然を守るため、パリピやマナー違反者をフル装備のサバイバルナイフと拳（肉球）で成敗しようとする熱血指導員猫。', 'シンプルなペン画の猫「きそさんせんにゃん」。腕章を着け、小さなホイッスルをくわえてビシッと敬礼している真面目でシュールな指導員マスコット。', 'minimalist ranger cat mascot named Kisosansen-nyan wearing a tiny park ranger armband and holding a safety whistle, standing at attention with a deadpan face, clean pen lines --ar 1:1', 'ぴぴーッ！にゃにゃー！', '「木曽三川公園の自然を守るにゃ！マナー違反者は肉球で成敗だにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(17, 'とだがわにゃん', 'とだがわにゃん', '戸田川緑地・橋の下のダンボール', 'Date(2023,3,24)', '戸田川緑地の橋の下でダンボールに入り、涼みながらBBQ客のおこぼれをもらって気ままに暮らす愛嬌たっぷりの野良猫キャンパー。', 'シンプルなペン画の猫「とだがわにゃん」。『ご自由にどうぞ』と書かれた小さなダンボール箱に入り、ちょこんと顔を出して真顔で見つめている脱力系イラスト。', 'minimalist cute cat mascot named Todagawa-nyan sitting cozy inside a small cardboard box, poking its head out with a comical deadpan expression, simple black ink drawing --ar 1:1', 'にゃ〜ん（がさがさ）', '「戸田川緑地の橋の下のダンボールが快適すぎて動けないにゃ〜」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(18, 'ごーるでんなににゃん', 'ごーるでんなににゃん', 'ゴールデンウィーク・連休の幻', 'Date(2023,4,1)', 'GW（ゴールデンウィーク）の存在を耳が遠いふりをして聞き流し、連休の宝探しと昼酒に溺れる猫。', 'シンプルなペン画の猫「ごーるでんなににゃん」。金色に輝く王冠を斜めにかぶり、ビールジョッキを持って恍惚の真顔で立っている脱力系マスコット。', 'minimalist funny cat mascot named Golden-nani-nyan wearing a slightly crooked gold party crown and holding a tiny cold beer mug with a deadpan blissful face, pen art --ar 1:1', 'ぷはーっ！にゃーうんにゃ！', '「ゴールデンウィークの存在は聞こえないふりして昼酒を飲むにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(19, 'ろけっとにゃん', 'ろけっとにゃん', '映画『ガーディアンズ・オブ・ギャラクシー』ロケット', 'Date(2023,4,8)', 'アライグマではなく猫。凶暴な重火器をぶっ放そうとするが、アベンニャーズの仲間たちとガールズバーに入り浸る。', 'シンプルなペン画の猫「ろけっとにゃん」。背中に大きすぎる手作りロケットランチャーを背負い、ドヤ顔（真顔）で立っている脱力系イラスト。', 'minimalist scrappy cat mascot named Rocket-nyan carrying an oversized comical sci-fi blaster on its back with a determined deadpan face, clean black line art --ar 1:1', 'だだだだっ！にゃーっ！', '「重火器ぶっ放すアライグマ…じゃなくて猫のロケットだにゃ！ガールズバー行くにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(20, 'あぶりじろうにゃん / ゆでたろうにゃん', 'あぶりじろうにゃん', '炙り焼き・茹で蟹・居酒屋メニュー', 'Date(2023,4,15)', '山道家に居候して居酒屋を開業しようとしたり、蟹や牡蠣を獲るためにベーリング海へ旅立とうとする呑兵衛コンビ猫。', 'シンプルなペン画の猫コンビ「あぶりじろうにゃん＆ゆでたろうにゃん」。一匹はガストーチ、もう一匹はお鍋を持ち、並んで真顔で立っている脱力系イラスト。', 'minimalist duo cat mascots named Aburi-Jiro-nyan and Yudetaro-nyan, one holding a mini cooking blowtorch and the other holding a small soup pot, deadpan expressions, pen lines --ar 1:1', 'ぼわっ！じゅーっ！（カンパイ）', '「山道家に居候して居酒屋を開業するにゃ！炙りたての蟹を食うにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(21, 'てんとうむしにゃん / はらぐろてんとうにゃん', 'てんとうむしにゃん', '鞍ヶ池公園のテントウムシ・お洒落キャンパーライト', 'Date(2023,4,29)', '鞍ヶ池から連れてこられたテントウムシ柄の猫。お洒落キャンパーライトの明かりに吸い寄せられて釘付けになり動けなくなる。', 'シンプルなペン画の猫「てんとうむしにゃん」。背中に赤い水玉模様のテントウムシの羽を生やし、眩しいランタンの光をじっと見つめている脱力系マスコット。', 'minimalist cute cat mascot named Tentomushi-nyan with red spotted ladybug wings on its back, staring intently at a glowing camping lantern with a deadpan face, pen drawing --ar 1:1', 'じーーーーっ（パタパタ）', '「テントウムシの羽でお洒落キャンパーライトの明かりに吸い寄せられたにゃ…」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(22, 'あいどるにゃん', 'あいどるにゃん', '推しの子・地下アイドルブーム', 'Date(2023,5,5)', '星の瞳を持つ究極のアイドル猫。サイリウムを振り回し、ファンからのおひねり（チュールと現金）をがっぽり回収する。', 'シンプルなペン画の猫「あいどるにゃん」。目に小さな星マークが入り、両手にピンクのサイリウムを持って真顔でアイドルポーズをとっている脱力系イラスト。', 'minimalist cute idol cat mascot named Idol-nyan with sparkling star eyes, holding tiny pink glow sticks in both paws with a stoic deadpan stage pose, simple pen art --ar 1:1', 'きらーん☆にゃにゃー！', '「星の瞳の究極アイドルにゃ！サイリウム振ってチュールとおひねり投げるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(23, 'じゃっどりーむにゃん', 'じゃっどりーむにゃん', 'サマージャンボ宝くじ（ドリームジャンボ）', 'Date(2023,5,12)', '7億円当選の夢を語り、当選金で六番町に黄金の猫城を建てようと妄想を膨らませる宝くじ猫。', 'シンプルなペン画の猫「じゃっどりーむにゃん」。宝くじの束を扇子のように広げて持ち、大富豪気取りの真顔で立っている脱力系マスコット。', 'minimalist lucky cat mascot named Jackdream-nyan fanning a stack of lottery tickets in its paw with a haughty deadpan expression, clean black ink pen lines --ar 1:1', 'うひひ！にゃーうんにゃ！', '「サマージャンボ7億円当たったら六番町に黄金の猫城を建てるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(24, 'わいまーけっとにゃん', 'わいまーけっとにゃん', 'Y.MARKET BREWING（ワイマーケット・ブルーイング）', 'Date(2023,5,19)', '名古屋のクラフトビール「ワイマーケット」の缶を両手に持ち、昼間からぷはーっとクラフトビールを飲み比べる猫。', 'シンプルなペン画の猫「わいまーけっとにゃん」。クラフトビールの缶を抱え、ほんのり頬を染めながら真顔で立っている脱力系イラスト。', 'minimalist cute cat mascot named Y-Market-nyan holding a colorful craft beer can, with tiny blush marks on its cheeks and a deadpan stoic face, simple pen drawing --ar 1:1', 'ぷはーーっ！（ゴクゴク）', '「ワイマーケットのクラフトビール最高にゃ！昼間から飲み比べるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(25, 'へるぱんぎーにゃん', 'へるぱんぎーにゃん', '夏風邪・ヘルパンギーナ', 'Date(2023,5,26)', '喉の痛みを引き起こす夏のウイルス猫。喉にアイスクリームを塗りたくって冷やそうとする。', 'シンプルなペン画の猫「へるぱんぎーにゃん」。首に保冷剤を巻き、アイスキャンディーをくわえて潤んだ目で立っている脱力系マスコット。', 'minimalist funny cat mascot named Herpangina-nyan wearing an ice pack scarf around its neck, holding an ice pop with a deadpan face, clean black line art --ar 1:1', 'ふにゃぁ…（ちゅーちゅー）', '「喉が痛くてたまらないにゃ…保冷剤巻いてアイスキャンディー吸うにゃ…」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(26, 'くらいぶにゃん / どみにゃんと', 'くらいぶにゃん', 'ゲーム『FF16』クライヴ・ドミナント（ビールの召喚獣）', 'Date(2023,6,3)', '「麦とホップのドミナント」。冷蔵庫のキンキンに冷えたビールを召喚する力を持ち、由美さんをナイトとして従える。', '黒い革鎧を着たシンプルなペン画の猫「くらいぶにゃん」。背中に大きな剣を背負い、手から冷たいビールの泡を出しているシュールなファンタジー猫。', 'minimalist dark fantasy cat mascot named Clive-nyan wearing black leather armor with a greatsword on its back, creating beer foam from its paw with a serious deadpan face, pen lines --ar 1:1', 'ふっ…うにゃにゃー（シュパッ）', '「我は麦とホップのドミナント…キンキンの生ビールを召喚せよにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(27, 'ひるがのにゃん', 'ひるがのにゃん', 'ひるがの高原キャンプ場・ひるがの虫', 'Date(2023,6,17)', '「ひるがの虫と仲良くなる草」を持ち込みパニックを引き起こす。後に虫専用居酒屋（スライストマト等）を開業してもてなす。', 'シンプルなペン画の猫「ひるがのにゃん」。頭に高原の高山植物を生やし、虫取り網を持って虫たちと行進している脱力系イラスト。', 'minimalist nature cat mascot named Hirugano-nyan with a tiny alpine flower on its head, holding a butterfly net with a funny deadpan face, clean line drawing --ar 1:1', 'わしゃわしゃ！にゃーっ！', '「ひるがの虫と仲良くなる草を持ってきたにゃ！虫専用居酒屋開店だにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(28, 'よかびとにゃん', 'よかびとにゃん', 'アウトドアブランド「YOCABITO」・猫用キャンプギア', 'Date(2023,6,23)', '猫用ナイフ、猫用トング、猫用フライパン、人間も飲めるマタタビ酒などを開発し、市場調査と称して売り込みをかけるギア開発猫。', 'シンプルなペン画の猫「よかびとにゃん」。小さなシェラカップとミニチュアトングを持ち、キャンプエプロンを着けて真顔で立っている脱力系マスコット。', 'minimalist outdoor gear cat mascot named Yocabito-nyan wearing a tiny camping apron and holding a miniature sierra cup with a stoic deadpan expression, pen art --ar 1:1', 'かんかん！にゃにゃー！', '「猫用フライパンと人間も飲めるマタタビ酒の市場調査に来たにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(29, 'ねこいちねこざにゃん', 'ねこいちねこざにゃん', '保護猫イベント「ネコ市ネコ座」・猫グッズ開発', 'Date(2023,7,7)', 'ネコ市ネコ座に出品するため、猫用バスソルトや猫用全自動乾燥機など奇想天外な猫グッズを開発する。', 'シンプルなペン画の猫「ねこいちねこざにゃん」。法被を着て頭に手ぬぐいを巻き、手作りの猫おもちゃを並べた露店の前に立っている脱力系イラスト。', 'minimalist festival vendor cat mascot named Nekoichi-Nekoza-nyan wearing a tiny happi coat and headband, standing stoically behind a miniature craft stall, simple pen art --ar 1:1', 'へいらっしゃい！にゃにゃー！', '「ネコ市ネコ座で手作りの怪しい猫用全自動乾燥機を売るにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(30, 'あうとどあにゃんすたー', 'あうとどあにゃんすたー', 'アウトドア雑誌の表紙モデル・スーパースター猫', 'Date(2023,7,9)', '伝説のアウトドアトップモデル。過密スケジュールで寝る間もなく撮影会をこなし、テントの前で完璧なポーズを決める。', 'シンプルなペン画の猫「あうとどあにゃんすたー」。サングラスをかけ、首に派手なアウトドアバンダナを巻いてモデル立ちしている脱力系マスコット。', 'minimalist top model cat mascot named Outdoor-Nyanstar wearing cool dark sunglasses and an outdoor bandana, striking a deadpan fashion pose, clean pen line art --ar 1:1', 'ふっ…（キリッ）', '「アウトドア雑誌の表紙を飾るカリスマトップモデルだにゃ。サインは後でにゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(31, 'えいてぃしっくすにゃん / はんどらーにゃん', 'えいてぃしっくすにゃん', 'アニメ『86-エイティシックス-』・多脚機甲ジャガーノート', 'Date(2023,7,15)', '過酷な戦場（会社の労働）をジャガーノート型三輪車で駆け抜ける。有給休暇を申請するがハンドラーに強制出勤させられる。', 'シンプルなペン画の猫「えいてぃしっくすにゃん」。4本足の多脚メカスーツに乗り込み、小さな通信ヘッドセットをつけて真顔で操縦している脱力系イラスト。', 'minimalist mecha cat mascot named Eighty-Six-nyan piloting a tiny four-legged spider tank with a serious deadpan face and military headset, simple black ink drawing --ar 1:1', 'がしゃんがしゃん！にゃーっ！', '「ジャガーノート型三輪車で出勤だにゃ！有給休暇を強制却下されたにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(32, 'あるぺんあうとどあにゃん', 'あるぺんあうとどあにゃん', 'Alpen Outdoors・温泉＆半額クーポン', 'Date(2023,7,20)', 'アルペンアウトドアーズの割引クーポン（期限切れ）を配り、逃げ出したアブたちを回収するためにツアーを組む店員猫。', 'シンプルなペン画の猫「あるぺんあうとどあにゃん」。アルペンアウトドアーズのロゴ風エプロンを着て、割引チラシを持って立っている脱力系マスコット。', 'minimalist store clerk cat mascot named Alpen-Outdoors-nyan wearing a green store apron and holding a tiny coupon flyer with a deadpan helpful expression, pen lines --ar 1:1', 'いらっしゃいませーにゃ！', '「アルペンの期限切れ半額クーポンあげるからアブ回収ツアーに参加するにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(33, 'あぶにゃん / はえにゃん', 'あぶにゃん', 'キャンプ場のアブ・ハエ・バランタイン30年', 'Date(2023,7,20)', '大量に放たれて車やテントを占拠するアブの集団。観光ストライキを起こし、バランタイン30年を要求して居座る。', 'シンプルなペン画の猫「あぶにゃん」。背中に透明な羽を生やし、縞模様のお腹でブーンと飛びながら真顔でウイスキーグラスを見つめている脱力系イラスト。', 'minimalist funny bug cat mascot named Abu-nyan with translucent insect wings and striped belly, hovering stoically next to a tiny whiskey glass, clean line art --ar 1:1', 'ぶーーーん！（チクッ）', '「バランタイン30年を差し出すまでテントを占拠してストライキするにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(34, 'うしおにゃん / しんぺいにゃん', 'うしおにゃん', 'アニメ『サマータイムレンダ』小舟潮・網代慎平', 'Date(2023,7,27)', '日名子島の世界線から現れ、本物の健介さんか「影」かを見極めようとする。影を撃退するつもりが大宴会になる。', '水着を着たシンプルなペン画の猫「うしおにゃん」。首にペンダントを下げ、右目に青い光を宿して真顔で立っている脱力系ヒロイン猫。', 'minimalist anime heroine cat mascot named Ushio-nyan wearing a one-piece swimsuit and glowing blue right eye, standing stoically with a deadpan face, clean pen lines --ar 1:1', 'うにゃっ！しんぺいくん！', '「この健介は本物かにゃ？影なら撃退して大宴会を開く必要があるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(35, 'ひかりにゃん / えなにゃん', 'ひかりにゃん', 'アニメ『凪のあすから』先島光・エナ（皮膚の膜）', 'Date(2023,8,4)', '海の中で呼吸できる皮膚の膜「エナ」を求めて地上にやってくる。ガンプラのエアリアルやバルバトスにエナを着せようとする。', 'シンプルなペン画の猫「ひかりにゃん」。体がうっすらと透明な膜（エナ）で包まれ、小さなシュノーケルをつけて真顔で立っている脱力系イラスト。', 'minimalist underwater cat mascot named Hikari-nyan with a delicate translucent membrane surrounding its body, wearing tiny swim goggles with a deadpan face, pen drawing --ar 1:1', 'ぷくぷく…にゃーにゃ', '「海の中で息ができるエナ（膜）をガンプラに着せて遊ぶにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(36, 'ゔぃにゃん / どらむにゃん', 'ゔぃにゃん', 'ドラマ『VIVANT』別班・ドラム', 'Date(2023,8,11)', '日本の平和を守る超エリート別班猫組織。大柄な「どらむにゃん」はスマホの音声合成アプリで「超優秀〜！」と喋る。', 'シンプルなペン画の丸々と太った猫「どらむにゃん」。スマホを胸元に掲げ、親指を立てて満面の真顔で立っている脱力系マスコット。', 'minimalist chubby operative cat mascot named Drum-nyan holding a tiny smartphone and giving a stoic thumbs up with a deadpan funny expression, clean black line art --ar 1:1', '（ポチッ）うにゃ優秀〜！', '「音声合成アプリ『超優秀〜！』。別班の極秘任務を遂行中にゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(37, 'やなにゃん', 'やなにゃん', '岐阜の鮎やな・落ち鮎', 'Date(2023,8,25)', '鮎を丸呑みして吐き出す観光名物「猫簗（ねこやな）」から脱走し、太り過ぎてダイエット特訓に励む猫。', 'シンプルなペン画の猫「やなにゃん」。口に大きな鮎をくわえ、竹で組まれたやな（仕掛け）の上でドヤ顔（真顔）で立っている脱力系イラスト。', 'minimalist river fishing cat mascot named Yana-nyan holding a whole fresh sweetfish in its mouth, standing proudly on a bamboo fish trap with a deadpan face, simple pen art --ar 1:1', 'もぐもぐ！ごっくん！', '「猫簗（ねこやな）から脱走したにゃ！鮎を丸呑みしすぎて太っちゃったにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(38, 'ふじまきにゃん', 'ふじまきにゃん', 'レミオロメン藤巻亮太「粉雪」・健康志向パスタ', 'Date(2023,9,2)', '「粉雪」を熱唱しながら、有機野菜サンドや和定食を自炊する超健康志向猫。コロンビアの軽量靴で熊本まで歩いて仕入れに行く。', 'シンプルなペン画の猫「ふじまきにゃん」。マイクスタンドの前に立ち、首にストールを巻いて熱唱（口真一文字）している脱力系ボーカル猫。', 'minimalist singer cat mascot named Fujimaki-nyan standing in front of a retro microphone stand wearing a winter scarf, singing passionately with a deadpan face, clean pen lines --ar 1:1', 'こなーーーゆきーーー！にゃ！', '「粉雪を熱唱しながら有機野菜パスタを自炊する健康志向猫だにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(39, 'ひがししらかわにゃん', 'ひがししらかわにゃん', '岐阜県東白川村・シャインマスカット・清流', 'Date(2023,9,10)', '東白川村のカフェ＆キャンプ場マスコット。海がないのに「裏の川で獲れたマグロ刺身（1万円）」を売り出したり、シャインマスカットを植えまくる。', 'シンプルなペン画の猫「ひがししらかわにゃん」。頭に緑のシャインマスカットの房を乗せ、手作りの値札を持って立っている商魂たくましい脱力系マスコット。', 'minimalist rural merchant cat mascot named Higashi-Shirakawa-nyan with a cluster of green shine muscat grapes on its head, holding a tiny price tag with a deadpan face, pen lines --ar 1:1', 'へい毎度！にゃにゃー！', '「東白川村の裏の川で獲れたマグロ刺身（1万円）はいかがかにゃ？」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(40, 'しんじだいにゃん / しんせかいにゃん', 'しんじだいにゃん', '居酒屋「新時代」・名物「伝串」', 'Date(2023,9,23)', '居酒屋チェーン「新時代」の凄腕経営者猫。ころにゃんをバイトリーダーから店長にスピード出世させてこき使い、伝串ピラミッドを築く。', 'シンプルなペン画の猫「しんじだいにゃん」。居酒屋のハチマキを巻き、山盛りの鶏皮焼き鳥（伝串ピラミッド）を抱えて立っている脱力系イラスト。', 'minimalist izakaya owner cat mascot named Shinjidai-nyan wearing a twisted headband and holding a giant pyramid of crispy chicken skin skewers with a deadpan proud face, pen art --ar 1:1', '伝串ピラミッド完成にゃ！', '「居酒屋新時代の店長だにゃ！ころにゃんをバイトリーダーにしてこき使うにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(41, 'いーあすにゃん / いーきのうにゃん / いーおとついにゃん', 'いーあすにゃん', 'ショッピングモール「イーアス春日井」・過去と未来', 'Date(2023,9,30)', 'イーアス春日井の守護猫。地下に潜むライバル「いーきのうにゃん」「いーおとついにゃん」を現金で買収し、一大テーマパーク「いーいっしゅうかん」を築く。', 'シンプルなペン画の猫「いーあすにゃん」。ショッピングバッグを両手に提げ、ネオン看板のサングラスをかけて真顔で立っている脱力系マスコット。', 'minimalist shopping mall cat mascot named Iias-nyan carrying multiple retail shopping bags in both paws, wearing funny neon glasses with a deadpan expression, clean line art --ar 1:1', 'いーあす！いーきのう！にゃ！', '「イーアス春日井を買い占めてテーマパーク『いーいっしゅうかん』を作るにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(42, 'ごじらにゃん', 'ごじらにゃん', '映画『ゴジラ-1.0』・怪獣王', 'Date(2023,10,6)', '背びれを生やした怪獣猫。海から上陸して熱線を吐こうとするが、タカスのチョコとタコピーを渡されてあっさり懐く。', '背中にギザギザの恐竜の背びれが生えたシンプルなペン画の猫「ごじらにゃん」。小さな口から青い光線（煙）を吹きながら真顔で立っている脱力怪獣イラスト。', 'minimalist kaiju cat mascot named Godzilla-nyan with spiky dorsal fins along its back, puffing a tiny blue atomic breath with a deadpan comical expression, clean pen lines --ar 1:1', 'がおーーーっ！（ぼっ）', '「怪獣王ごじらにゃんだにゃ！タカスのチョコくれたら大人しくなるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(43, 'みすにゃーべる', 'みすにゃーべる', '映画『マーベルズ』ミズ・マーベル・ジャンピング土下座', 'Date(2023,10,14)', '宇宙からやってきたヒーロー猫。クレーマー対策として「ジャンピング土下座」を必殺技に繰り出し、ユニバーサル猫スタジオを設立する。', 'シンプルなペン画の猫「みすにゃーべる」。ヒーローマントを羽織り、空中からダイナミックに土下座ポーズを決めているシュールで可愛いマスコット。', 'minimalist superhero cat mascot named Ms-Marvel-nyan wearing a tiny fluttering cape, frozen mid-air in a dramatic jumping bow (dogeza) with a deadpan face, simple line art --ar 1:1', 'ずさーーーーっ！（ジャンピング土下座）', '「必殺ジャンピング土下座だにゃ！クレームは全てこれで解決するにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(44, 'いちのみやにゃん', 'いちのみやにゃん', '一宮モーニング発祥の地・開運の壺・お札', 'Date(2023,10,20)', '一宮モーニングの豪華さを誇る猫。山道家に「買えばモーニング代が浮く開運の壺」やお札を売りつけようとする霊感商法（？）猫。', 'シンプルなペン画の猫「いちのみやにゃん」。頭に分厚いバタートーストを乗せ、怪しげな開運の壺を抱えて真顔で立っている脱力系イラスト。', 'minimalist cafe merchant cat mascot named Ichinomiya-nyan balancing a thick slice of buttered toast on its head, holding a traditional ceramic vase with a deadpan expression, pen lines --ar 1:1', 'つぼ買いませんかにゃ〜？', '「一宮モーニング代が浮く開運の壺（30万円）はいかがかにゃ？」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(45, 'ざうおにゃん', 'ざうおにゃん', '釣船茶屋ざうお・店内釣り堀・三日三晩の祈り', 'Date(2023,10,26)', 'ざうおの店内で魚が足りなくなり、多摩川まで魚を口に溜めに行って流される。足りない伊勢海老を「三日三晩のお祈り」で召喚しようとする。', 'シンプルなペン画の猫「ざうおにゃん」。小さな木造船に乗り、釣り竿を垂らして魚をじっと待っている脱力系釣り猫イラスト。', 'minimalist fisherman cat mascot named Zauo-nyan sitting aboard a tiny wooden fishing boat holding a miniature fishing rod, staring intently at the water with a deadpan face, pen lines --ar 1:1', '釣れるまで帰らんニャ！（じーっ）', '「ざうおの店内で伊勢海老が足りないから三日三晩お祈りして召喚するにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(46, 'ぎょよむすーぱーあみかにゃん', 'ぎょよむすーぱーあみかにゃん', '業務用食品スーパー「アミカ」・冷凍エビカニ', 'Date(2023,11,1)', '業務用スーパーアミカで冷凍カニや特大エビのブロックをまとめ買いし、解凍して生き返らせようとする錬金術猫。', 'シンプルなペン画の猫「あみかにゃん」。巨大な冷凍カニの脚を抱え、買い物カートを押して真顔で立っている脱力系マスコット。', 'minimalist wholesale supermarket cat mascot named Amika-nyan holding an oversized frozen crab leg, pushing a mini shopping cart with a deadpan stoic face, simple pen drawing --ar 1:1', 'カニ解凍中だにゃ！（しゃきーん）', '「業務スーパーアミカの巨大冷凍カニを解凍して錬金術で生き返らせるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(47, 'くりすますまーけっとにゃん / くりけっとにゃん', 'くりすますまーけっとにゃん', '久屋大通公園クリスマスマーケット・ホットワイン', 'Date(2023,11,11)', 'クリスマスマーケットでスパイス入りホットワインを飲みまくり、略して「くりけっとにゃん」と呼ばれて泥酔する猫。', 'シンプルなペン画の猫「くりすますまーけっとにゃん」。サンタ帽をかぶり、湯気立つホットワインのマグカップを両手で持って立っている脱力系イラスト。', 'minimalist holiday cat mascot named Christmas-Market-nyan wearing a tiny Santa hat, holding a steaming mug of spiced mulled wine with a deadpan festive expression, pen lines --ar 1:1', 'ひっく…ワインうまいニャ…', '「クリスマスマーケットでホットワイン飲みすぎて泥酔くりけっとになったにゃ…」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(48, 'すいーとおぶおれごんにゃん', 'すいーとおぶおれごんにゃん', 'チーズケーキ専門店「スイートオブオレゴン」', 'Date(2023,11,18)', 'オレゴン州の森の妖精を気取り、濃厚なオレゴンチーズケーキをホールで抱えてプレゼントしにやってくる猫。', 'シンプルなペン画の猫「すいーとおぶおれごんにゃん」。カウボーイハットをかぶり、ホールチーズケーキの箱を抱えて真顔で立っている脱力系イラスト。', 'minimalist baker cat mascot named Sweet-of-Oregon-nyan wearing a tiny cowboy hat and holding a whole round cheesecake box with a deadpan stoic face, clean black line art --ar 1:1', 'メリークリスマスにゃ！（どすん）', '「スイートオブオレゴンの濃厚チーズケーキをホールでプレゼントしに来たにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(49, 'たつにゃん / そそりたつにゃん', 'たつにゃん', '2024年 辰年・昇り龍', 'Date(2024,0,4)', '辰年を祝して龍の着ぐるみを着て登場。健介さんに「そそりたつにゃん」と名付けられて天高く聳え立つ。', 'シンプルなペン画の猫「たつにゃん」。緑色のドラゴンの着ぐるみを頭からすっぽりかぶり、小さな角を生やして真顔で立っている脱力系イラスト。', 'minimalist dragon cat mascot named Tatsu-nyan wearing a green dragon costume hood with tiny horns, standing stoically with a comical deadpan face, clean black ink lines --ar 1:1', '天高くそそり立つにゃー！', '「辰年記念のドラゴンの着ぐるみを着て天高く聳え立つにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(50, 'すわるにゃん / しゃがむにゃん', 'すわるにゃん', 'パチスロ台・パワースポット・座る姿勢', 'Date(2024,0,10)', '椅子に座るだけでその場所をパワースポットに変える猫。双子の弟「しゃがむにゃん」と共にパチスロ台に座り続ける。', 'シンプルなペン画の猫「すわるにゃん」。小さな丸椅子に背筋をピンと伸ばしてちょこんと座り、無表情で正面を見つめている脱力系マスコット。', 'minimalist cute cat mascot named Suwaru-nyan sitting perfectly upright on a tiny round stool with an intensely blank deadpan stare, simple black pen lines --ar 1:1', 'すちゃっ…（無言の仁王座り）', '「椅子に座るだけでその場所をパチスロパワースポットに変えてみせるにゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(51, 'みゅしゃにゃん', 'みゅしゃにゃん', '画家アルフォンス・ミュシャ・日展', 'Date(2024,0,15)', '日展に感化され、華麗なアール・ヌーヴォー風の装飾枠の中で裸体の健介さんが酒を飲む名画を描く巨匠（おっさん）猫。', 'シンプルなペン画の猫「みゅしゃにゃん」。華やかなアール・ヌーヴォー風の花柄の円形装飾フレームの中にちょこんと座り、絵筆を持っている脱力系イラスト。', 'minimalist art nouveau cat mascot named Mucha-nyan framed by delicate circular floral vine patterns, holding a tiny paintbrush with a deadpan artistic face, pen art --ar 1:1', '美とは…酒にゃ（ふっ）', '「華麗なアールヌーヴォー枠の中で裸の健介が酒を飲む名画を描く巨匠にゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(52, 'はにーぽったにゃん / どれいくにゃん', 'はにーぽったにゃん', '映画『ハリー・ポッター』魔法学校・マンドレイク（叫ぶ植物）', 'Date(2024,0,22)', '魔法界から修学旅行でやってきた魔法使い猫。植木鉢から引き抜くと「粉雪」を大合唱する植物猫「どれいくにゃん」を育てる。', 'シンプルなペン画の猫「はにーぽったにゃん」。丸メガネと魔法使いの三角帽子をかぶり、植木鉢から引き抜いたマンドレイク猫を持って立っている脱力系イラスト。', 'minimalist wizard cat mascot named Honey-Potter-nyan wearing round glasses and a pointed witch hat, holding a tiny screaming mandrake cat plant from a pot with a deadpan face, pen lines --ar 1:1', '引っこ抜くニャ！（こなーーゆきー！）', '「植木鉢から引き抜くと粉雪を大熱唱するどれいくにゃんを育ててるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(53, 'おどかわにゃん / どぶにゃん', 'おどかわにゃん', 'アニメ『オッドタクシー』小戸川・ドブ', 'Date(2024,0,29)', '個人タクシーを営むセイウチ風の無口な猫。由美さんを乗せて名古屋の街を右折だけで一周したり、移動お布団タクシーを開発する。', 'シンプルなペン画の猫「おどかわにゃん」。運転手の制帽をかぶり、タクシーのハンドルを持って真顔で前を見つめている脱力系イラスト。', 'minimalist taxi driver cat mascot named Odokawa-nyan wearing a vintage chauffeur cap, holding a miniature steering wheel with a tired stoic deadpan face, clean line art --ar 1:1', 'どちらまで？（メーターカチカチ）', '「個人タクシーおどかわにゃんだにゃ。右折だけで名古屋を一周するにゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(54, 'たきびにゃん / きゃんぷふぁいやーにゃん', 'たきびにゃん', '冬キャンプの焚き火・直火', 'Date(2024,1,5)', '寒さに耐えかねて自ら発火し焚き火と化した猫。怒るとキャンプファイヤー級の大炎上を起こして五右衛門風呂を沸かす。', 'シンプルなペン画の猫「たきびにゃん」。頭の上に小さな焚き火の炎がメラメラと灯り、暖まりながら真顔で立っている脱力系マスコット。', 'minimalist cozy campfire cat mascot named Takibi-nyan with a small flickering flame atop its head, sitting warmly with a peaceful deadpan expression, simple pen drawing --ar 1:1', 'ぼわーーっ！（ぽかぽか）', '「寒すぎて自ら発火して焚き火になったにゃ！五右衛門風呂も沸かすにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(55, 'だぶるしーびーにゃん', 'だぶるしーびーにゃん', 'West Coast Brewing（WCB）クラフトビール', 'Date(2024,1,13)', '静岡用宗のクラフトビールWCBの化身。ビールサーバーの魔法のレバーを操作し、フルーティーなIPAで山道夫妻を泥酔させる。', 'シンプルなペン画の猫「だぶるしーびーにゃん」。両手にIPAビールの缶を持ち、ビールの王冠をベレー帽のようにかぶっている脱力系イラスト。', 'minimalist craft beer cat mascot named WCB-nyan wearing a beer bottle cap as a beret, holding two IPA beer cans with a cheerful deadpan face, clean line art --ar 1:1', 'WCBのIPAで乾杯にゃ！', '「静岡用宗のクラフトビールだにゃ！フルーティーな苦味で酔っ払うにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(56, 'かえでにゃん', 'かえでにゃん', 'オフィス用個室テント開発・キャンプ用品メーカー', 'Date(2024,1,19)', '会社で仕事中にこっそり引きこもれる「完全防音オフィス用個室テント」を布とハサミだけで開発し、注文が殺到する敏腕開発猫。', 'シンプルなペン画の猫「かえでにゃん」。デスク用の小さなドーム型テントの中にすっぽり入り、真顔でキーボードを叩いている脱力系イラスト。', 'minimalist office worker cat mascot named Kaede-nyan sitting snugly inside a miniature cubicle desk tent, typing on a tiny laptop with a deadpan expression, pen lines --ar 1:1', 'カタカタカタ…（引きこもり）', '「完全防音オフィス用個室テントを開発したにゃ！仕事サボり放題だにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(57, 'はちみつにゃん / ちーずにゃん', 'はちみつにゃん', '蜂蜜＆チーズ・ピザ＆チーズフォンデュ', 'Date(2024,1,25)', '蜂蜜の壺を持つ「はちみつにゃん」と、マイチーズフォンデュを持ち歩く「ちーずにゃん」。お寿司をチーズにディップして悪魔の食べ物を生み出す。', 'シンプルなペン画の猫コンビ「はちみつにゃん＆ちーずにゃん」。一匹はハチミツの壺、もう一匹は穴あきチーズを持ち、並んで真顔で立っている脱力系イラスト。', 'minimalist duo cat mascots named Hachimitsu-nyan and Cheese-nyan, one holding a honey pot and the other holding Swiss cheese, standing stoically side by side, simple line art --ar 1:1', 'チーズとハチミツどろりんにゃ！', '「お寿司をチーズフォンデュとハチミツにディップして悪魔の飯を作るにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(58, 'せんきんにゃん', 'せんきんにゃん', '栃木の銘酒「仙禽（せんきん）」・日本酒ペアリング', 'Date(2024,2,11)', '仙禽のプレミアム日本酒の一升瓶を抱え、高級寿司とのペアリングを提案しつつ自分でお酒を飲み干して赤ら顔になるソムリエ猫。', 'シンプルなペン画の猫「せんきんにゃん」。日本酒のとっくりとおちょこを持ち、着物を着てほんのり赤い顔で立っている脱力系イラスト。', 'minimalist sake sommelier cat mascot named Senkin-nyan wearing a traditional kimono, holding a sake bottle and ceramic cup with a flushed deadpan face, clean pen lines --ar 1:1', 'クゥ〜ッ！仙禽の一升瓶最高にゃ！', '「栃木の銘酒『仙禽』と高級寿司をペアリングして自分で飲み干すにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(59, 'じょぶちゅんにゃん', 'じょぶちゅんにゃん', 'テレビ番組『ジョブチューン』・超一流料理人審査', 'Date(2024,2,18)', '「全員一致で合格！」の札を掲げる審査員猫。巨大なしゃもじを持って「突撃！お隣の晩ごはん」のように他人の食卓へ乱入する。', 'シンプルなペン画の猫「じょぶちゅんにゃん」。『合格』と書かれた審査プレートを高く掲げ、巨大なしゃもじを持って真顔で判定している脱力系マスコット。', 'minimalist food judge cat mascot named Jobtune-nyan holding up a round ''PASS'' score paddle and a giant rice paddle with a strict deadpan face, simple black ink drawing --ar 1:1', '満場一致で合格ニャーーッ！', '「ジョブチューン審査員にゃ！巨大しゃもじを持ってお隣の晩ご飯に突撃にゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(60, 'ゔぃそんにゃん', 'ゔぃそんにゃん', '三重県多気町「VISON（ヴィソン）」・おしゃれ野宿', 'Date(2024,2,25)', 'VISONの美しい大自然の中でゼインアーツのテントを張り、カエルのジャン／ポール／エヴァンと共にサバイバル野宿を満喫するお洒落猫。', 'シンプルなペン画の猫「ゔぃそんにゃん」。お洒落なシェルターテントの横で、木製マグカップを持って澄ました真顔で立っている脱力系イラスト。', 'minimalist stylish camper cat mascot named Vison-nyan standing next to a sleek modern geometric camping shelter, holding a wooden kuksa cup with a deadpan expression, pen art --ar 1:1', 'ヴィソンでおしゃれ野宿にゃ！', '「VISONの自然の中でゼインアーツのテント張ってカエルと野宿するにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(61, 'くくにゃん / おきとまにゃん', 'くくにゃん', 'ZANE ARTS テント「KUKU-2」＆「OKITOMA-2」', 'Date(2024,3,1)', '山道家に新しく迎えられた大型テント「KUKU-2」の化身。大きな体で屋台ずしを爆食いし、ドナドナされる先輩「おきとまにゃん」からエースの座を引き継ぐ。', 'シンプルなペン画のぽっちゃり巨大猫「くくにゃん」。背中にドーム型テントを背負い、お寿司の皿を山盛りに積んで真顔で立っている脱力系イラスト。', 'minimalist large chubby cat mascot named Kuku-nyan carrying a spacious camping tent shell on its back, standing beside a tall stack of sushi plates with a deadpan face, pen lines --ar 1:1', '屋台ずし全種類もってこいニャ！', '「大型テントKUKU-2だにゃ！おきとま先輩のエースの座を奪い取ったにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(62, 'ひこねにゃん', 'ひこねにゃん', '彦根城お花見・ダンディな黒スーツ＆サングラス', 'Date(2024,3,15)', '彦根のお花見で登場。黒スーツにシルクハット、サングラスを着けてシガレットチョコと豆乳を片手に「裏社会のダンディなボス」を気取る。', 'シンプルなペン画の猫「ひこねにゃん」。黒いスーツとシルクハット、黒いサングラスを着用し、シガレットチョコをくわえてポーズをとる脱力系ギャング猫。', 'minimalist dandy cat mascot named Hikone-nyan wearing a tiny black mobster suit, top hat, and sunglasses, holding a chocolate cigarette with a comical deadpan face, clean line art --ar 1:1', 'シガレットチョコくわえてダンディにゃ', '「黒スーツとサングラスで決めた裏社会のボスにゃ。豆乳を奢ってくれにゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(63, 'いずこうげんにゃん', 'いずこうげんにゃん', '伊豆高原・GWドライブ', 'Date(2024,4,1)', '伊豆の渋滞でのろのろ運転に慣れきった猫。軽トラの荷台に揺られて名古屋までやってきて健介さんの倉庫で部品出しを手伝わされる。', 'シンプルなペン画の猫「いずこうげんにゃん」。小さな車のハンドルの輪っかを首にかけ、温泉タオルを頭に乗せて真顔で立っている脱力系イラスト。', 'minimalist travel cat mascot named Izu-Kogen-nyan wearing a tiny onsen towel on its head and holding a toy car steering wheel with a deadpan tired face, simple pen art --ar 1:1', 'のろのろ運転で温泉行くにゃ〜', '「伊豆の渋滞に巻き込まれて軽トラの荷台で名古屋まで運ばれてきたにゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(64, 'きんにくにゃん', 'きんにくにゃん', '筋トレブーム・「筋肉は裏切らない」', 'Date(2024,4,14)', '「筋肉は裏切らない！」とダンベルを持ち上げてディスコでゴーゴーするが、風邪をひいて「ほどほどの筋肉が一番」とあっさり宗旨替えする。', 'シンプルなペン画の猫「きんにくにゃん」。小さなダンベルを両手で持ち、上腕二頭筋を力こぶのように強調しながら真顔で立っている脱力系マスコット。', 'minimalist fitness cat mascot named Kinniku-nyan holding tiny dumbbell weights in its paws, flexing its arms with a completely deadpan unamused face, clean black pen lines --ar 1:1', '筋肉は裏切らないニャ！（ムキムキ）', '「ダンベル持ち上げてディスコ行くにゃ！風邪ひいたから筋トレやめるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(65, 'もんすたーにゃん', 'もんすたーにゃん', '靴の中敷き（インソール）・消臭スプレー開発', 'Date(2024,4,20)', '靴の中敷きに可愛いモンスターを描いて販売。さらに消臭スプレーを調合するが、最終的に巨大な「モンスターハウス」を建てて住み着く。', 'シンプルなペン画の猫「もんすたーにゃん」。靴の中敷き（インソール）を両手に持ち、小さな消臭スプレーボトルを腰にぶら下げている脱力系イラスト。', 'minimalist quirky cat mascot named Monster-nyan holding a pair of illustrated shoe insoles and a mini deodorizing spray bottle with a stoic deadpan expression, pen drawing --ar 1:1', '中敷きモンスターハウス完成にゃ！', '「靴の中敷きに消臭スプレーかけて巨大なモンスターハウスを建てるにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(66, 'もんじゃにゃん', 'もんじゃにゃん', 'ご当地もんじゃ焼き・スノーピークフラットバーナー', 'Date(2024,5,3)', '背中に鉄板とフラットバーナーを背負い、全国で「小倉あずきもんじゃ」「ういろうもんじゃ」など前衛的なご当地もんじゃを焼き歩くキャンパー猫。', 'シンプルなペン画の猫「もんじゃにゃん」。背中に四角い鉄板を背負い、小さなもんじゃ用ヘラ（ハガシ）を両手に持って真顔で構えている脱力系イラスト。', 'minimalist street food cat mascot named Monja-nyan carrying a flat iron griddle on its back, holding two tiny metal spatulas with a deadpan culinary face, clean line art --ar 1:1', '小倉あずきもんじゃ焼くニャ！', '「フラットバーナー背負って全国で前衛的なご当地もんじゃを焼き歩くにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(67, 'でっどぷーるにゃん / あんちひーろーにゃん', 'でっどぷーるにゃん', '映画『デッドプール』・ショートケーキの苺復讐劇', 'Date(2024,5,10)', 'ショートケーキの苺を食べられた復讐に燃え、街中のケーキ屋のショートケーキを買い占めて配り歩くお茶目な復讐者猫。', '赤と黒のツートンマスクをかぶったシンプルなペン画の猫「でっどぷーるにゃん」。ショートケーキの苺をフォークに刺して掲げ、真顔で立っている脱力系イラスト。', 'minimalist antihero cat mascot named Deadpool-nyan wearing a red and black masked hood, holding a single strawberry on a tiny dessert fork with a funny deadpan face, pen lines --ar 1:1', '俺ちゃんのイチゴ返せニャーーッ！', '「ショートケーキの苺を食べられた復讐にケーキ屋を買い占めるデッドプールにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(68, 'あじさいにゃん', 'あじさいにゃん', '形原温泉あじさいの里・500円の鐘', 'Date(2024,5,24)', '形原温泉あじさいの里のマスコット。紫陽花の花冠をかぶり、500円を投入すると鳴らせる開運の鐘を全力で乱打する。', 'シンプルなペン画の猫「あじさいにゃん」。頭に大きな紫陽花（アジサイ）の満開の花帽子をかぶり、小さな鐘の紐を引いている脱力系マスコット。', 'minimalist floral cat mascot named Ajisai-nyan wearing a blooming hydrangea flower hat, holding a bell rope with a peaceful deadpan expression, simple black ink drawing --ar 1:1', 'カランカラン！（500円投入）', '「あじさいの花冠かぶって500円の開運の鐘を全力で乱打するにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(69, 'しぼりたてにゃん', 'しぼりたてにゃん', '生搾りオレンジジュース自販機・早搾り対決', 'Date(2024,5,25)', '新鮮なオレンジを手当たり次第に生搾りして早飲み対決を挑む。最終的に電車の非常ドアコックまで搾ろうとして止められる。', 'シンプルなペン画の猫「しぼりたてにゃん」。オレンジ絞り器の上に乗り、果汁滴るグラスの横で真顔で仁王立ちしている脱力系イラスト。', 'minimalist juice bar cat mascot named Shiboritate-nyan sitting atop a manual citrus squeezer next to a fresh glass of orange juice with a deadpan face, clean line art --ar 1:1', 'ぎゅーーーっ！オレンジ生搾りだにゃ！', '「電車の非常ドアコックまで生搾りしようとして駅員に怒られたにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(70, 'ぱんとにわにゃん', 'ぱんとにわにゃん', 'ベーカリーカフェ「パンと庭」', 'Date(2024,6,1)', '古民家風の庭園で焼きたてのクロワッサンやハードパンを焼き、庭の芝生でお昼寝しながら優雅にカフェ営業する猫。', 'シンプルなペン画の猫「ぱんとにわにゃん」。頭に焼きたてのフランスパン（バゲット）を乗せ、庭の手入れ用ハサミを持って立っている脱力系イラスト。', 'minimalist bakery garden cat mascot named Pan-to-Niwa-nyan with a crusty French baguette on its head, holding tiny gardening shears with a deadpan face, pen lines --ar 1:1', 'パンと庭でお昼寝カフェにゃ〜', '「焼きたてバゲットの香りに包まれて芝生で優雅に二度寝するにゃ〜」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(71, 'べんてんじまにゃん / もうしょにゃん', 'べんてんじまにゃん', '浜名湖・弁天島温泉・赤鳥居＆猛暑', 'Date(2024,6,9)', '弁天島の赤い鳥居を背負って登場。猛暑熱波を操る「もうしょにゃん」とタッグを組み、商業施設の冷房と戦いながらビールを要求する。', 'シンプルなペン画の猫「べんてんじまにゃん」。頭の上に赤い神社の鳥居を乗せ、海パンを穿いて真顔で浮き輪を持っている脱力系マスコット。', 'minimalist coastal cat mascot named Bentenjima-nyan with a miniature red torii gate on its head, holding a summer swim tube with a deadpan stoic face, simple pen art --ar 1:1', '赤鳥居かついで猛暑ビールにゃ！', '「弁天島の赤鳥居を背負ってきたにゃ！猛暑熱波の中でビールを要求するにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(72, 'めんびぎにゃん', 'めんびぎにゃん', 'アパレルブランド「MEN''S BIGI」・フラッグファッション', 'Date(2024,6,22)', 'MEN''S BIGIの襟付きシャツやスナフキン柄タオルを身にまとい、四角い布を羽織るだけの「フラッグファッション」を提案して大流行させる。', 'シンプルなペン画のお洒落猫「めんびぎにゃん」。洗練されたストライプ柄の襟付きシャツを着て、四角い布をマントのように羽織り澄ました顔で立っているイラスト。', 'minimalist fashionable cat mascot named Men''s-Bigi-nyan wearing a crisp collared button-down shirt and a stylish flag drape with a deadpan chic face, clean line art --ar 1:1', 'MEN''S BIGIの襟付きシャツでキメるにゃ', '「四角い布を羽織るだけのフラッグファッションを流行らせてみせるにゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(73, 'うるばにゃん', 'うるばにゃん', '映画『デッドプール＆ウルヴァリン』ウルヴァリン', 'Date(2024,6,29)', 'アダマンチウムの長い爪を持つ気難しい猫。鍵を開けようとしてドアノブを破壊し、山道家のベランダにテントを張って住み着く。', '黄色のスーツを着たシンプルなペン画の猫「うるばにゃん」。両手から3本ずつ金属の鋭い爪をシャキーンと出し、険しい真顔で立っている脱力系ヒーロー猫。', 'minimalist grumpy superhero cat mascot named Wolva-nyan wearing yellow suit accents with three metal claws extending from each paw, sporting an intensely funny deadpan scowl, pen art --ar 1:1', 'シャキーン！（爪ジャキッ）', '「ドアノブを爪で破壊しちゃったにゃ…ベランダにテント張って住み着くにゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(74, 'こまがねにゃん / にほんかもしかにゃん', 'こまがねにゃん', '中央アルプス駒ヶ根ロープウェイ・千畳敷カール・日本カモシカ', 'Date(2024,7,19)', '駒ヶ根から名古屋に遊びに来た猫。夜になるとサングラスのイケオジ「けんてぃーこ」に変身する健介さんに居酒屋で大宴会を開き二日酔いになる。', 'シンプルなペン画の猫「こまがねにゃん」。首にロープウェイのゴンドラ型ベルをつけ、高山植物のリュックを背負って立っている脱力系登山猫イラスト。', 'minimalist mountain ropeway cat mascot named Komagane-nyan wearing a tiny gondola bell and hiking backpack with a comical deadpan stoic face, simple pen lines --ar 1:1', 'ロープウェイで下山してきたにゃ！', '「駒ヶ根から名古屋に遊びに来たにゃ！イケオジけんてぃこと居酒屋行くにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(75, 'でいりーふぁうすとにゃん', 'でいりーふぁうすとにゃん', '即日配送サービス「デイリーファースト」・びっくり箱人形', 'Date(2024,7,26)', '注文した荷物（ガンプラ等）を自作のびっくり箱人形にすり替えて届ける迷惑配達員猫。人形がバズってプレミア化する。', 'シンプルなペン画の猫「でいりーふぁうすとにゃん」。配達員の青いキャップをかぶり、バネでビヨヨヨンと飛び出すびっくり箱を持って真顔で立っているイラスト。', 'minimalist courier cat mascot named Daily-Fast-nyan wearing a blue delivery cap and holding a spring-loaded jack-in-the-box toy with a deadpan face, clean line art --ar 1:1', 'びよよよ〜ん！（びっくり箱）', '「ガンプラの配達荷物を自作びっくり箱人形にすり替えてお届けしたにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(76, 'ろーすとびーふにゃん / どりにゃん', 'ろーすとびーふにゃん', '極上自家製ローストビーフ＆ドリアン', 'Date(2024,8,2)', '最高峰のローストビーフを焼き上げるためスパイス探しの旅に出る。強烈な香りを放つドリアン猫「どりにゃん」と意気投合して朝まで飲み明かす。', 'シンプルなペン画の猫「ろーすとびーふにゃん」。美しいピンク色のローストビーフの塊を皿に乗せて掲げ、真顔で立っている脱力系イラスト。', 'minimalist gourmet cat mascot named Roast-Beef-nyan proudly presenting a platter with a savory slice of roast beef, deadpan culinary expression, simple pen drawing --ar 1:1', 'ピンクの極上ローストビーフだにゃ！', '「ドリアン猫と意気投合して強烈な匂いの中で朝まで飲み明かしたにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(77, 'ひらばりめんきょにゃん', 'ひらばりめんきょにゃん', '平針運転免許試験場・三輪車免許・イケメン免許', 'Date(2024,8,10)', '勝手に他人の顔写真を隠し撮りして「イケメン免許証」や「三輪車ゴールド免許」を枕元に置いていく免許センターの猫。', 'シンプルなペン画の猫「ひらばりめんきょにゃん」。首から大きなゴールド運転免許証をぶら下げ、カメラを構えて真顔で立っている脱力系マスコット。', 'minimalist license bureau cat mascot named Hirabari-Menkyo-nyan wearing a gold driver''s license badge around its neck, holding a vintage camera with a deadpan face, pen lines --ar 1:1', 'パシャッ！イケメン免許交付にゃ！', '「勝手に寝顔を隠し撮りして三輪車ゴールド免許を枕元に置いていくにゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(78, 'あずーりにゃん', 'あずーりにゃん', 'イタリアンレストラン「アズーリ」・薬膳イタリアン・猫カフェ', 'Date(2024,8,24)', 'イタリア国旗を背負った腰の低いシェフ猫。「ぼったくってすみませ〜ん」と言いながら初心者の森の拾い物食材で絶品料理を作る。', 'イタリア国旗カラーのスカーフを巻いたシンプルなペン画の猫「あずーりにゃん」。ピザピール（ピザ用木べら）を持ち、深くお辞儀しながら真顔で見つめているイラスト。', 'minimalist Italian chef cat mascot named Azzurri-nyan wearing a tricolor Italian neckerchief, holding a wooden pizza peel with a comical bowing deadpan face, clean line art --ar 1:1', 'ぼったくってすみませ〜んにゃ！', '「初心者の森の拾い物食材で薬膳イタリアン作って平謝りするシェフにゃ」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(79, 'おにやんまにゃん', 'おにやんまにゃん', '虫除けオニヤンマ君・変装メガネ（丸メガネ＋付け鼻＋ちょび髭）', 'Date(2024,8,25)', '巨大なオニヤンマの羽を持つ猫。虫を威嚇するはずが、タレ目の変装メガネ（鼻メガネ）をかけて愛嬌を振りまき地下アイドルになる。', 'シンプルなペン画の猫「おにやんまにゃん」。背中にオニヤンマの大きなトンボの羽を生やし、黒ぶち丸メガネと付け鼻の変装メガネをかけて真顔で立っているイラスト。', 'minimalist disguise cat mascot named Oniyanma-nyan with giant dragonfly wings on its back, wearing novelty disguise glasses (round frames with fake nose and mustache), deadpan face, pen lines --ar 1:1', '鼻メガネで地下アイドルデビューにゃ！', '「オニヤンマの羽で虫除けするはずが変装メガネで愛嬌を振りまくにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(80, 'しろいきりんにゃん', 'しろいきりんにゃん', '白いキリン・移動式ピザ窯ウーニャーイーツ', 'Date(2024,8,30)', '首の長い白いキリン猫。背中に本格的な石窯ピザ窯を背負い、焼きたての絶品ピザを無料で配達して街中を喜ばせる。', '首が少し長くて白いシンプルなペン画の猫「しろいきりんにゃん」。背中に煙突付きの小さな石窯ピザ窯を背負い、焼きたてピザを持って立っている脱力系イラスト。', 'minimalist white giraffe cat mascot named Shiroi-Kirin-nyan with a slightly elongated neck, carrying a miniature brick pizza oven with a chimney on its back, deadpan face, pen art --ar 1:1', '焼きたてピザお届けウーニャーイーツにゃ！', '「首長白いキリンにゃ！背中の石窯ピザ窯で無料ピザを配り歩くにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(81, 'ぽろきちにゃん / しじみにゃん', 'ぽろきちにゃん', '初心者の森のジビエ・しじみ採集', 'Date(2024,9,7)', '初心者の森で採集したシジミに愛着が湧き、「シジミは食材ではなく家族！」と主張して守り育てる自然派猫。', 'シンプルなペン画の猫「しじみにゃん」。大きなシジミ貝の殻を頭に帽子のようにかぶり、川辺で真顔で立っている脱力系マスコット。', 'minimalist cute river cat mascot named Shijimi-nyan wearing a glossy black freshwater clam shell as a hat, standing near water with a deadpan stoic expression, clean pen lines --ar 1:1', 'しじみは食材じゃなく家族だにゃ！', '「初心者の森のシジミ貝を頭にかぶって自然と共生するエコ猫だにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(82, 'おーれにゃん / まんどれいくにゃん', 'おーれにゃん', '温泉宿ビュッフェ・マンドレイクの温泉養子', 'Date(2024,9,15)', '温泉宿の豪華朝食ビュッフェを愛する猫。初心者の森で夜泣きしていたマンドレイクを温泉（薬草湯）に入れて養子にし、WCBの苦味ビールを開発する。', 'シンプルなペン画の猫「おーれにゃん」。頭に温泉タオルを乗せ、小さな木桶に浸かったマンドレイク（顔つき大根）を抱えて真顔で立っている脱力系イラスト。', 'minimalist onsen cat mascot named Ohre-nyan wearing a head towel, holding a tiny wooden bath bucket with a baby mandrake root inside, deadpan expression, simple pen drawing --ar 1:1', 'マンドレイクを薬草温泉に入れるにゃ！', '「夜泣きするマンドレイクを温泉に入れて養子にしWCB苦味ビールを作るにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(83, 'よいちにゃん / たわしデザイナーけんてぃこ', 'よいちにゃん', '松阪牛・ファイヤーパレード・芸術的たわし', 'Date(2024,9,21)', '松阪牛を求めて旅する猫。コンロの炎上事件を経て、けんてぃこ（健介さん）の考案した「美しさを追求し使いやすさを犠牲にした芸術的たわし」を全財産で押し付けられる。', 'シンプルなペン画の猫「よいちにゃん」。両手に大きな亀の子束子（たわし）を掲げ、誇らしげな真顔で立っている脱力系芸術マスコット。', 'minimalist artistic cat mascot named Yoichi-nyan holding two traditional scrubbing brushes (tawashi) high in the air with a proud deadpan expression, clean black line art --ar 1:1', '芸術的たわしを押し売りするにゃ！', '「使いやすさを犠牲にして美を追求したけんてぃこデザインたわしだにゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(84, 'きせつおやこにゃん', 'きせつおやこにゃん', '秋の訪れを告げる妖精親子・クーリングオフ', 'Date(2024,9,28)', '季節の移り変わりを告げる善人すぎる妖精親子。高額スマホ契約やオレオレ詐欺に引っかかりそうになるたびクーリングオフで救出される。', 'シンプルなペン画の大小の猫親子「きせつおやこにゃん」。親猫と子猫が並び、それぞれ紅葉したモミジの葉を頭に乗せて真顔で正面を見つめている脱力系イラスト。', 'minimalist parent and child cat mascots named Kisetsu-Oyako-nyan, both with red autumn maple leaves on their heads, standing side by side with identical deadpan expressions, pen lines --ar 1:1', 'にゃーうんにゃ！（ぴょこっ）', '「きせつおやこにゃんだにゃ！秋の訪れを告げる善人すぎる妖精親子にゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(85, 'ぽろのかくれがにゃん', 'ぽろのかくれがにゃん', '隠れ家レストラン「PORO」・秘密の合言葉', 'Date(2024,10,4)', '六番町にある秘密の隠れ家猫。「東回りに3回転・拍手2回・『やっほほい』」の儀式を行うと扉が開いて美味しいワインとお肉を振る舞う。', 'シンプルなペン画の猫「ぽろのかくれがにゃん」。小さな秘密の鍵を首から下げ、アンティークな木製ドアの陰から真顔でチラリと覗いている脱力系イラスト。', 'minimalist speakeasy cat mascot named Poro-no-Kakurega-nyan peeking out from behind a tiny rustic wooden door, wearing an antique skeleton key necklace with a deadpan face, pen art --ar 1:1', 'にゃーうんにゃ！（ぴょこっ）', '「ぽろのかくれがにゃんだにゃ！六番町にある秘密の隠れ家猫にゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(86, 'つじぐちにゃん', 'つじぐちにゃん', 'パティシエ辻口博啓・栗のバウムクーヘン', 'Date(2024,10,11)', '伝説の小麦・究極のバター・奇跡の牛乳・中津川の栗を集めて至高のバウムクーヘンを焼き上げる、巨匠パティシエ猫。', 'シンプルなペン画の猫「つじぐちにゃん」。背の高いコック帽をかぶり、年輪の美しいバウムクーヘンを片手に持って真顔でポーズをとる脱力系マスコット。', 'minimalist master pastry chef cat mascot named Tsujiguchi-nyan wearing a tall chef''s hat, holding a slice of layered baumkuchen cake with a stoic deadpan expression, clean line art --ar 1:1', 'にゃーうんにゃ！（ぴょこっ）', '「つじぐちにゃんだにゃ！伝説の小麦・究極のバター・奇跡の牛乳・中津川の栗を集めて至高のバウムクーヘンを焼き上げる、巨匠パティシエ猫にゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
(87, 'らすてぃこにゃん兄弟（1〜4） / らこすてにゃん / らてすこにゃん', 'らすてぃこにゃん', '岐阜のベーカリーカフェ「ラスティコ」・山盛りモーニング', 'Date(2024,11,2)', '岐阜のラスティコ1〜4号店を統括する4兄弟猫。山盛りのパンが付くモーニングを提供し、名前が似ている「ラコステにゃん（ワニ柄）」と縄張り争いをする。', 'シンプルなペン画の猫「らすてぃこにゃん」。山盛りのクロワッサンやキッシュが入ったバスケットを両手で抱え、真顔で立っている脱力系イラスト。', 'minimalist bakery cat mascot named Rustico-nyan holding an overflowing basket of croissants and bread with a comical deadpan stoic face, clean black ink lines --ar 1:1', 'にゃーうんにゃ！（ぴょこっ）', '「らすてぃこにゃんだにゃ！岐阜のラスティコ1〜4号店を統括する4兄弟猫にゃ！」', TRUE, NULL, NULL, FALSE, '[]'::jsonb, '[]'::jsonb),
